mapper.select:
SELECT t.id, t.theme_name, t.price, t.thumbnail_url, t.theme_code,
CASE WHEN tp.id IS NOT NULL OR t.is_default = TRUE THEN TRUE ELSE FALSE END AS is_owned, CASE WHEN m.theme_id = t.id THEN TRUE ELSE FALSE END AS is_applied
FALSE AS is_owned, FALSE AS is_applied
FROM theme t
LEFT JOIN theme_purchase tp ON tp.theme_id = t.id AND tp.member_id = #{memberId} LEFT JOIN member m ON m.id = #{memberId}
WHERE t.status = 'ON_SALE' ORDER BY t.created_at DESC LIMIT #{limit} OFFSET #{offset}
